  1	/**
  2	 * Tests for ralph replacement — kspec ralph deprecation and built-in agent setup.
  3	 *
  4	 * Verifies that kspec ralph commands show a helpful migration error, and that
  5	 * kspec setup creates built-in task-worker and pr-reviewer agent definitions.
  6	 *
  7	 * Task: @implement-ralph-replacement
  8	 * Spec: @ralph-replacement
  9	 */
 10	
 11	import { describe, it, expect, beforeEach, afterEach } from "vitest";
 12	import * as fs from "node:fs/promises";
 13	import * as path from "node:path";
 14	import * as YAML from "yaml";
 15	import { spawnSync } from "node:child_process";
 16	import {
 17	  CLI_PATH,
 18	  createTempDir,
 19	  cleanupTempDir,
 20	  initGitRepo,
 21	  kspec,
 22	} from "./helpers/cli.js";
 23	
 24	// ─── Helpers ─────────────────────────────────────────────────────────────────
 25	
 26	interface CliResult {
 27	  stdout: string;
 28	  stderr: string;
 29	  exitCode: number;
 30	}
 31	
 32	function runCli(args: string[], cwd: string): CliResult {
 33	  const result = spawnSync("node", [CLI_PATH, ...args], {
 34	    cwd,
 35	    encoding: "utf-8",
 36	    timeout: 30000,
 37	    env: { ...process.env, KSPEC_AUTHOR: "@test" },
 38	  });
 39	  return {
 40	    stdout: result.stdout || "",
 41	    stderr: result.stderr || "",
 42	    exitCode: result.status ?? 1,
 43	  };
 44	}
 45	
 46	/**
 47	 * Create a minimal kspec project in a temp dir (traditional layout, not shadow branch).
 48	 */
 49	async function setupMinimalProject(dir: string): Promise<void> {
 50	  initGitRepo(dir);
 51	  await fs.writeFile(
 52	    path.join(dir, "kynetic.yaml"),
 53	    YAML.stringify({ kynetic: "1", title: "Test Project" }),
 54	    "utf-8",
 55	  );
 56	  await fs.writeFile(
 57	    path.join(dir, "kynetic.meta.yaml"),
 58	    YAML.stringify({
 59	      kynetic_meta: "1.0",
 60	      agents: [],
 61	      workflows: [],
 62	      conventions: [],
 63	      observations: [],
 64	      skills: [],
 65	      includes: [],
 66	    }),
 67	    "utf-8",
 68	  );
 69	}
 70	
 71	// ─── Tests ────────────────────────────────────────────────────────────────────
 72	
 73	// AC: @ralph-replacement ac-1
 74	describe("kspec ralph deprecation", () => {
 75	  it("shows migration error when kspec ralph run is invoked", () => {
 76	    const result = runCli(["ralph", "run"], process.cwd());
 77	
 78	    // Should exit with code 1
 79	    expect(result.exitCode).toBe(1);
 80	
 81	    // AC: @trait-error-guidance ac-1 — description of what went wrong
 82	    expect(result.stderr).toMatch(/kspec ralph has been replaced/i);
 83	
 84	    // AC: @ralph-replacement ac-1 — lists equivalent commands
 85	    expect(result.stderr).toContain("kspec ralph run");
 86	    expect(result.stderr).toContain("kspec agent dispatch start");
 87	    expect(result.stderr).toMatch(
 88	      /kspec ralph run\s+→\s+kspec agent dispatch start/,
 89	    );
 90	  });
 91	
 92	  it("shows migration error when kspec ralph end-loop is invoked", () => {
 93	    const result = runCli(["ralph", "end-loop"], process.cwd());
 94	
 95	    // Should exit with code 1
 96	    expect(result.exitCode).toBe(1);
 97	
 98	    // AC: @trait-error-guidance ac-1 — description of what went wrong
 99	    expect(result.stderr).toMatch(/kspec ralph has been replaced/i);
100	
101	    // AC: @ralph-replacement ac-1 — lists equivalent commands
102	    expect(result.stderr).toContain("kspec agent end-loop");
103	  });
104	
105	  it("shows kspec setup suggestion in migration message", () => {
106	    const result = runCli(["ralph"], process.cwd());
107	
108	    // AC: @trait-error-guidance ac-2 — suggested action to resolve
109	    expect(result.stderr).toContain("kspec setup");
110	  });
111	});
112	
113	// AC: @ralph-replacement ac-2
114	describe("kspec setup built-in agents", () => {
115	  let tempDir: string;
116	
117	  beforeEach(async () => {
118	    tempDir = await createTempDir();
119	    await setupMinimalProject(tempDir);
120	  });
121	
122	  afterEach(async () => {
123	    await cleanupTempDir(tempDir);
124	  });
125	
126	  it("creates task-worker and pr-reviewer agents when project has no agents", async () => {
127	    // Run setup (no-hooks to keep it fast in tests)
128	    const result = await kspec("setup --no-hooks --skip-skills", tempDir);
129	    expect(result.exitCode).toBe(0);
130	
131	    // Read the meta manifest
132	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
133	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
134	      agents?: Array<{ id: string; dispatch?: unknown[] }>;
135	    };
136	
137	    const agents = raw.agents || [];
138	    const agentIds = agents.map((a) => a.id);
139	
140	    // AC: @ralph-replacement ac-2 — built-in worker and reviewer created
141	    expect(agentIds).toContain("task-worker");
142	    expect(agentIds).toContain("pr-reviewer");
143	  });
144	
145	  it("task-worker has dispatch rules for task.in_progress/task.ready/task.needs_work with eligible filter", async () => {
146	    await kspec("setup --no-hooks --skip-skills", tempDir);
147	
148	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
149	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
150	      agents?: Array<{
151	        id: string;
152	        dispatch?: Array<{ on: string; filter?: { automation?: string } }>;
153	      }>;
154	    };
155	
156	    const worker = (raw.agents || []).find((a) => a.id === "task-worker");
157	    expect(worker).toBeDefined();
158	
159	    const dispatch = worker!.dispatch || [];
160	    const events = dispatch.map((r) => r.on);
161	
162	    // AC: @ralph-replacement ac-2 — worker: task.in_progress + task.ready + task.needs_work with eligible filter
163	    expect(events).toContain("task.in_progress");
164	    expect(events).toContain("task.ready");
165	    expect(events).toContain("task.needs_work");
166	
167	    // Should have automation: eligible filter
168	    const inProgressRule = dispatch.find((r) => r.on === "task.in_progress");
169	    expect(inProgressRule?.filter?.automation).toBe("eligible");
170	    const readyRule = dispatch.find((r) => r.on === "task.ready");
171	    expect(readyRule?.filter?.automation).toBe("eligible");
172	    const needsWorkRule = dispatch.find((r) => r.on === "task.needs_work");
173	    expect(needsWorkRule?.filter?.automation).toBe("eligible");
174	  });
175	
176	  it("pr-reviewer has dispatch rule for task.pending_review", async () => {
177	    await kspec("setup --no-hooks --skip-skills", tempDir);
178	
179	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
180	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
181	      agents?: Array<{
182	        id: string;
183	        dispatch?: Array<{ on: string }>;
184	      }>;
185	    };
186	
187	    const reviewer = (raw.agents || []).find((a) => a.id === "pr-reviewer");
188	    expect(reviewer).toBeDefined();
189	
190	    const events = (reviewer!.dispatch || []).map((r) => r.on);
191	
192	    // AC: @ralph-replacement ac-2 — reviewer: task.pending_review
193	    expect(events).toContain("task.pending_review");
194	  });
195	
196	  it("does not duplicate agents when run twice (idempotent)", async () => {
197	    await kspec("setup --no-hooks --skip-skills", tempDir);
198	    await kspec("setup --no-hooks --skip-skills", tempDir);
199	
200	    const metaPath = path.join(tempDir, "kynetic.meta.yaml");
201	    const raw = YAML.parse(await fs.readFile(metaPath, "utf-8")) as {
202	      agents?: Array<{ id: string }>;
203	    };
204	
205	    const agentIds = (raw.agents || []).map((a) => a.id);
206	    const workerCount = agentIds.filter((id) => id === "task-worker").length;
207	    const reviewerCount = agentIds.filter((id) => id === "pr-reviewer").length;
208	
209	    expect(workerCount).toBe(1);
210	    expect(reviewerCount).toBe(1);
211	  });
212	});
