214	// AC: @ralph-replacement ac-6
215	describe("agent dispatch template section", () => {
216	  it("06-ralph-loop.md template references agent dispatch not ralph", async () => {
217	    // Resolve the template path relative to package root
218	    const templatePath = path.join(
219	      __dirname,
220	      "..",
221	      "templates",
222	      "agents-sections",
223	      "06-ralph-loop.md",
224	    );
225	    const content = await fs.readFile(templatePath, "utf-8");
226	
227	    // Should reference agent dispatch concepts
