248	  });
249	
250	  it("session checkpoint warns about uncommitted changes when they exist", async () => {
251	    // Create a file change to simulate uncommitted work
252	    await fs.writeFile(
253	      path.join(tempDir, "uncommitted.ts"),
254	      "// uncommitted work\n",
255	      "utf-8",
256	    );
257	
258	    // Session checkpoint should detect the dirty working tree and block
259	    const result = await kspec(
260	      "session checkpoint --json",
261	      tempDir,
262	    );
263	
264	    // In JSON mode, checkpoint exits 0 but outputs {"decision": "block", "reason": "..."}
265	    // when uncommitted changes are detected
266	    expect(result.exitCode).toBe(0);
267	    const output = JSON.parse(result.stdout.trim()) as { decision: string; reason: string };
268	    expect(output.decision).toBe("block");
269	    expect(output.reason).toContain("uncommitted changes");
270	  });
271	});
